const allIds=()=>new Set(Object.keys(KINDS).flatMap(k=>data[k].map(x=>x.id)));
/* IDs: '<packId>-<visible>'. The pack part is hidden (input, search, lists and references show the visible part only), so
   packs by different authors don't collide. Suggested visible IDs are '<CODE>-<6 digits>' using the smallest free number
   (numbers freed by deletion are reused). CODE is the kind's English initials; new kinds get a unique code automatically. */
const CODES={units:'U',weapons:'W',skills:'S',items:'I',missions:'DM',tmissions:'TM',flags:'F',terrains:'T',research:'R',hires:'H',evolutions:'E',fusions:'FU',achievements:'A'};
function codeOf(k){if(CODES[k])return CODES[k];const used=new Set(Object.values(CODES)),words=String(KINDS[k]?.en||k).toUpperCase().split(/[^A-Z]+/).filter(Boolean);let c=words.map(w=>w[0]).join('')||k.slice(0,2).toUpperCase(),last=words.at(-1)||c,i=1;while(used.has(c))c=c+(last[i++]||String(i));return CODES[k]=c;}
const pre=()=>(data.packId||'td-pack')+'-',shownId=id=>id&&String(id).startsWith(pre())?String(id).slice(pre().length):id;
function nextId(k){const ids=allIds(),c=codeOf(k);for(let n=0;;n++){const id=pre()+c+'-'+String(n).padStart(6,'0');if(!ids.has(id))return id;}}
// Old / imported IDs without the pack part get a suggested ID; references follow. ALIAS keeps old → new for this session.
const ALIAS={},ALIASK={};function migrateIds(){for(const k of Object.keys(KINDS)){if(!Array.isArray(data[k]))continue;for(const x of [...data[k]])if(x.id&&!String(x.id).startsWith(pre())){const to=nextId(k);ALIAS[x.id]=to;(ALIASK[k]=ALIASK[k]||{})[x.id]=to;renameId(k,x.id,to);}}}
// Extensions registered after a migration replay it on their own references.
const replayAliases=hook=>{for(const [k,m] of Object.entries(ALIASK))hook(k,id=>m[id]??id);};
const find=(k,id)=>data[k].find(x=>x.id===id);
const missionUnitIds=m=>[...(m.enemies||[]),...(m.waves||[]).flatMap(w=>w.enemies||[]),...(m.objective?.escortUnitId?[m.objective.escortUnitId]:[])];
/* Every ID link in the pack, in one place. mapRefs(kind, fn) rewrites links to `kind` (fn returns the new ID,
   or null to drop the link); refsOf(ownerKind, owner) lists [kind,id] pairs it points to. */
function mapRefs(k,fn){const list=a=>a&&a.map(fn).filter(Boolean);for(const f of EXT.mapRefs)f(k,fn);mapCondRefs(k,fn);
 if(k==='units'){for(const u of data.units)if(u.base){const n=fn(u.base);if(n)u.base=n;else{delete u.base;delete u.separate;}}for(const e of data.evolutions)for(const f of ['from','to'])if(e[f]){const n=fn(e[f]);if(n)e[f]=n;else delete e[f];}for(const fu of data.fusions){if(fu.materials)fu.materials=fu.materials.filter(m=>{const n=fn(m.unitId);if(n)m.unitId=n;return !!n;});if(fu.result?.unitId){const n=fn(fu.result.unitId);if(n)fu.result.unitId=n;else delete fu.result.unitId;}}}
 // Skill tree nodes reference pack skills by skillId; a deleted skill removes its node (and links to it).
 if(k==='skills')for(const u of data.units)if(u.pilotProfile?.skillIds)u.pilotProfile.skillIds=list(u.pilotProfile.skillIds);
 if(k==='skills')for(const u of data.units)if(u.skillTree){const gone=new Set();u.skillTree=u.skillTree.filter(n=>{if(!n.skillId)return true;const v=fn(n.skillId);if(v){n.skillId=v;return true;}gone.add(n.id);return false;});for(const n of u.skillTree)n.requires=(n.requires||[]).filter(r=>!gone.has(r));}
 if(k==='hires')for(const fu of data.fusions)if(fu.result?.hireId){const n=fn(fu.result.hireId);if(n)fu.result.hireId=n;else delete fu.result.hireId;}
 if(k==='weapons'||k==='skills'){const key=k==='weapons'?'weaponIds':'skillIds';for(const u of data.units)if(u[key])u[key]=list(u[key]);for(const it of data.items){if(it.equip?.[key])it.equip[key]=list(it.equip[key]);for(const e of it.effects||[]){const f=k==='weapons'?(e.type==='add_weapon'&&'weaponId'):((e.type==='add_skill'||e.type==='remove_skill')&&'skillId');if(f&&e[f]){const n=fn(e[f]);if(n)e[f]=n;else delete e[f];}}}}
 if(k==='units'){for(const m of data.missions){const walk=(o,ek,rk)=>{if(!o[ek])return;const keep=[],rows=[];o[ek].forEach((id,i)=>{const n=fn(id);if(n){keep.push(n);rows.push((o[rk]||[])[i]||'front');}});o[ek]=keep;if(o[rk]||rows.includes('back'))o[rk]=rows;};walk(m,'enemies','enemyRows');for(const w of m.waves||[])walk(w,'enemies','rows');if(m.objective?.escortUnitId){const n=fn(m.objective.escortUnitId);if(n)m.objective.escortUnitId=n;else delete m.objective.escortUnitId;}}for(const it of data.items)for(const e of it.effects||[])if(e.type==='recruit_unit'&&e.unitId){const n=fn(e.unitId);if(n)e.unitId=n;else delete e.unitId;}}
 if(k==='missions')for(const it of data.items)if(it.shop?.requiresMission){const n=fn(it.shop.requiresMission);if(n)it.shop.requiresMission=n;else{delete it.shop.requiresMission;if(!Object.keys(it.shop).length)delete it.shop;}}
 if(k==='flags'){const re=o=>{if(!o)return o;const out={};for(const [id,v] of Object.entries(o)){const n=fn(id);if(n)out[n]=v;}return Object.keys(out).length?out:undefined;};for(const m of data.missions){if(m.requires?.flags){const v=re(m.requires.flags);if(v)m.requires.flags=v;else delete m.requires.flags;}if(m.resultFlags)for(const r of ['win','lose','draw']){if(m.resultFlags[r]){const v=re(m.resultFlags[r]);if(v)m.resultFlags[r]=v;else delete m.resultFlags[r];}}for(const e of m.events||[])if(e.flags){const v=re(e.flags);if(v)e.flags=v;else delete e.flags;}for(const c of m.story?.choices||[])if(c.flags)c.flags=re(c.flags)||{};for(const top of ['requires','resultFlags'])if(m[top]&&!Object.keys(m[top]).length)delete m[top];}}
 if(k==='units')for(const m of data.missions)if(m.drops)m.drops=m.drops.filter(d=>{if(!d.unitId)return true;const n=fn(d.unitId);if(n)d.unitId=n;return !!n;});
 if(k==='units')for(const m of data.missions)for(const e of m.events||[])for(const f of ['unitId','requiredUnitId'])if(e[f]){const n=fn(e[f]);if(n)e[f]=n;else delete e[f];}
 if(k==='missions')for(const m of data.missions)if(m.requires?.missions)m.requires.missions=list(m.requires.missions);
 if(k==='items')for(const m of data.missions)if(m.requires?.items)m.requires.items=list(m.requires.items);
 const rekey=o=>{if(!o)return o;const out={};for(const [id,n] of Object.entries(o)){const x=fn(id);if(x)out[x]=n;}return out;};
 if(k==='research'){for(const x of data.research)if(x.requires)x.requires=list(x.requires);for(const h of data.hires)if(h.requires?.research)h.requires.research=list(h.requires.research);for(const it of data.items)if(it.shop?.requiresResearch){const n=fn(it.shop.requiresResearch);if(n)it.shop.requiresResearch=n;else{delete it.shop.requiresResearch;if(!Object.keys(it.shop).length)delete it.shop;}}}
 if(k==='units'){for(const x of data.research)if(x.unlock?.units)x.unlock.units=list(x.unlock.units);for(const x of data.research)if(x.unlock?.register)x.unlock.register=list(x.unlock.register);for(const h of data.hires)if(h.unitId){const n=fn(h.unitId);if(n)h.unitId=n;else delete h.unitId;}}
 if(k==='missions')for(const h of data.hires)if(h.requires?.missions)h.requires.missions=list(h.requires.missions);
 if(k==='items'){for(const x of data.research){if(x.unlock?.items)x.unlock.items=list(x.unlock.items);if(x.cost?.items)x.cost.items=rekey(x.cost.items);if(x.unlock?.grantItems)x.unlock.grantItems=rekey(x.unlock.grantItems);}for(const h of data.hires)if(h.requires?.items)h.requires.items=list(h.requires.items);}
 if(k==='items')for(const a of data.achievements)if(a.reward?.items){for(const id of Object.keys(a.reward.items)){const n=fn(id);if(n!==id){const v=a.reward.items[id];delete a.reward.items[id];if(n)a.reward.items[n]=v;}}}
 if(k==='items'){for(const m of data.missions)if(m.drops)m.drops=m.drops.filter(d=>{if(!d.itemId)return true;const n=fn(d.itemId);if(n)d.itemId=n;return !!n;});for(const it of data.items)for(const e of it.effects||[])if(e.type==='loot_box'&&e.table)e.table=e.table.filter(r=>{const n=fn(r.itemId);if(n)r.itemId=n;return !!n;});}}
// Every condition set inside an owner (top-level, drops, events, choices …), found by walking the object.
function condSets(o,out=[]){if(!o||typeof o!=='object')return out;if(Array.isArray(o)){for(const x of o)condSets(x,out);return out;}if(o.conds?.list)out.push(o);for(const [k,v] of Object.entries(o))if(k!=='conds'&&v&&typeof v==='object')condSets(v,out);return out;}
const condRefs=o=>condSets(o).flatMap(h=>h.conds.list.flatMap(c=>Object.entries(COND_REF).filter(([f])=>c[f]).map(([f,k])=>[k,c[f]])));
function mapCondRefs(k,fn){for(const ok of Object.keys(KINDS))for(const o of data[ok])for(const h of condSets(o)){h.conds.list=h.conds.list.filter(c=>{for(const [f,rk] of Object.entries(COND_REF))if(rk===k&&c[f]){const n=fn(c[f]);if(!n)return false;c[f]=n;}return true;});if(!h.conds.list.length)delete h.conds;}}
function refsOf(ok,o){const out=[];const add=(k,ids)=>{for(const id of ids||[])if(id)out.push([k,id]);};if(EXT.refs[ok])for(const [k,id] of EXT.refs[ok](o))add(k,[id]);for(const [k,id] of condRefs(o))add(k,[id]);
 if(ok==='evolutions')add('units',[o.from,o.to]);
 if(ok==='fusions'){add('units',[...(o.materials||[]).map(m=>m.unitId),o.result?.type!=='hire'?o.result?.unitId:null]);add('hires',[o.result?.type==='hire'?o.result?.hireId:null]);}
 if(ok==='units'){add('weapons',o.weaponIds);add('skills',o.skillIds);add('skills',(o.skillTree||[]).map(n=>n.skillId));add('skills',o.pilotProfile?.skillIds);add('units',[o.base]);}
 if(ok==='missions'){add('units',missionUnitIds(o));add('items',(o.drops||[]).map(d=>d.itemId));add('units',(o.drops||[]).map(d=>d.unitId));}
 if(ok==='missions'){add('flags',[...Object.keys(o.requires?.flags||{}),...['win','lose','draw'].flatMap(r=>Object.keys(o.resultFlags?.[r]||{})),...(o.events||[]).flatMap(e=>Object.keys(e.flags||{})),...(o.story?.choices||[]).flatMap(c=>Object.keys(c.flags||{}))]);add('units',(o.events||[]).flatMap(e=>[e.unitId,e.requiredUnitId]));add('missions',o.requires?.missions);add('items',o.requires?.items);}
 if(ok==='missions'){const tid=n=>data.terrains.find(t=>t.name===n)?.id;add('terrains',[tid(o.terrain),...(o.events||[]).map(e=>tid(e.terrain))]);}
 if(ok==='achievements')add('items',Object.keys(o.reward?.items||{}));
 if(ok==='research'){add('research',o.requires);add('units',o.unlock?.units);add('units',o.unlock?.register);add('items',[...(o.unlock?.items||[]),...Object.keys(o.cost?.items||{}),...Object.keys(o.unlock?.grantItems||{})]);}
 if(ok==='hires'){add('units',[o.unitId]);add('missions',o.requires?.missions);add('research',o.requires?.research);add('items',o.requires?.items);}
 if(ok==='items'){add('weapons',o.equip?.weaponIds);add('skills',o.equip?.skillIds);for(const e of o.effects||[]){if(e.type==='add_weapon')add('weapons',[e.weaponId]);if(e.type==='add_skill'||e.type==='remove_skill')add('skills',[e.skillId]);if(e.type==='recruit_unit')add('units',[e.unitId]);if(e.type==='loot_box')add('items',(e.table||[]).map(r=>r.itemId));}add('missions',[o.shop?.requiresMission]);add('research',[o.shop?.requiresResearch]);}
 return out;}
// Owners (any kind) that link to kind/id.
const usage=(k,id)=>Object.keys(KINDS).flatMap(ok=>data[ok].filter(o=>refsOf(ok,o).some(([rk,rid])=>rk===k&&rid===id)).map(o=>({kind:ok,item:o})));
// Renaming an ID rewrites every link to it.
function renameId(k,from,to){const x=find(k,from);x.id=to;mapRefs(k,id=>id===from?to:id);if(selectedId===from)selectedId=to;}
// id: the visible part typed by the author; self: the item's full ID.
function idProblem(id,self){if(!id)return 'IDが空です';if(!/^[A-Za-z0-9_-]+$/.test(id))return '半角英数字・_・- だけ使えます';if(pre()+id!==self&&allIds().has(pre()+id))return 'このIDはすでに使われています';return '';}

/* ---------- validation ---------- */
// Pack-wide check: field problems plus a count of items with issues.
function packIssues(){const out=[];if(!/^[A-Za-z0-9_-]+$/.test(data.packId||''))out.push('パックIDは半角英数字・_・-です');if(!data.name)out.push('パック名がありません');const bad=Object.keys(KINDS).flatMap(k=>data[k].filter(x=>issues(k,x).length).map(x=>KINDS[k].label+'「'+x.name+'」'));if(bad.length)out.push('問題のあるデータ'+bad.length+'件：'+bad.slice(0,5).join('・')+(bad.length>5?'…':''));return out;}
function issues(k,x){const out=[];if(!x.name)out.push('名前がありません');if(EXT.issues[k])out.push(...EXT.issues[k](x));if(k==='weapons'){try{C.weapon(x);}catch(e){out.push(e.message);}if((x.minRange??1)>(x.maxRange??1))out.push('最大射程は最小射程以上にしてください');}
 if(k==='skills'){if(x.tacticalOnly){const t=x.tactical||{};if(!(t.carry?.count>0||t.eject||t.enRegen>0||t.ammoRegen>0||t.carryCare?.on))out.push('マップ専用スキルにタクティカルの効果がありません');}else{try{C.skill({...x,id:x.id||'tmp'});}catch(e){out.push(e.message);}}}
 if(k==='units'&&x.base){const seen=new Set([x.id]);let b=find('units',x.base);while(b?.base){if(seen.has(b.id)){out.push('ベースユニットが循環しています');break;}seen.add(b.id);b=find('units',b.base);}}
 if(k==='units'){if(!x.weaponIds?.length)out.push('武装がありません（戦闘では標準攻撃になります）');if(x.size==null||x.move==null)out.push('サイズ・MOVEが未設定（タクティカルで使えません）');if(!x.deploy?.player&&!x.deploy?.enemy)out.push('味方・敵のどちらにも使わない設定です');}
 for(const [rk,id] of refsOf(k,x))if(!find(rk,id)&&!(k==='missions'&&rk==='units'&&missionUnitIds(x).includes(id)))out.push(KINDS[rk].label+'「'+id+'」が見つかりません');
 out.push(...condIssues(x));
 if(k==='evolutions'){if(!x.from||!x.to)out.push('進化前・進化後のユニットを選んでください');else if(x.from===x.to)out.push('進化前と進化後が同じユニットです');if(!x.conds?.list?.length)out.push('条件がありません（いつでも進化できます）');}
 if(k==='fusions'){if((x.materials||[]).length<2)out.push('素材は2体以上必要です');if(x.result?.type==='hire'?!x.result?.hireId:!x.result?.unitId)out.push('結果が未選択です');}
 if(k==='research'){try{C.research(x);}catch(e){out.push(e.message);}if((x.requires||[]).includes(x.id))out.push('自分自身を前提にしています');const loop=(id,seen=new Set())=>{if(seen.has(id))return true;seen.add(id);return (find('research',id)?.requires||[]).some(q=>loop(q,new Set(seen)));};if((x.requires||[]).some(q=>loop(q,new Set([x.id]))))out.push('前提研究が循環しています');}
 if(k==='hires'){try{C.hire({...x,id:x.id});}catch(e){out.push(e.message);}if(!x.unitId)out.push('雇うユニットが未選択です');}
 if(k==='terrains'){try{C.terrain(x);}catch(e){out.push(e.message);}if(data.terrains.some(t=>t.id!==x.id&&t.name===x.name))out.push('同じ名前の独自の地形があります');if(BUILTIN_TERRAINS.includes(x.name))out.push('標準の地形「'+x.name+'」を上書きします（意図した場合は問題ありません）');}
 if(k==='missions'){for(const n of [x.terrain||'標準',...(x.events||[]).map(e=>e.terrain).filter(Boolean)])if(!BUILTIN_TERRAINS.includes(n)&&!data.terrains.some(t=>t.name===n))out.push('地形「'+n+'」が見つかりません');}
 if(k==='items'){try{C.item(itemCore(x));}catch(e){out.push(e.message);}for(const e of x.effects||[]){if(e.type==='add_weapon'&&!e.weaponId)out.push('「武装追加」の武装が未選択');if(e.type==='add_skill'&&!e.skillId)out.push('「スキル習得」のスキルが未選択');if(e.type==='recruit_unit'&&!e.unitId)out.push('「ユニット加入」のユニットが未選択');}}
 if(k==='missions'){for(const d of x.drops||[]){const m=dropIssue(d);if(m)out.push(m);}const ids=missionUnitIds(x);for(const id of new Set(ids)){const u=find('units',id);if(!u)out.push('ユニット「'+id+'」が見つかりません');else if(id!==x.objective?.escortUnitId&&!u.deploy?.enemy)out.push('「'+u.name+'」は「敵として使う」がOFFです');}if(!x.enemies?.length)out.push('敵がいません');try{C.missionExt(x.drops?{...x,drops:x.drops.map(d=>d.unitId?{...d,itemId:d.unitId}:d)}:x);for(const r of x.rules||[])C.rule(r,x.id);}catch(e){out.push(e.message);}}
 return out;}

/* ---------- autosave ---------- */
function save(){try{localStorage.setItem(DRAFT,JSON.stringify(data));$('saveState').textContent='自動保存しました '+new Date().toLocaleTimeString('ja-JP');}catch(e){$('saveState').textContent='保存できませんでした';}}
function load(){try{const d=JSON.parse(localStorage.getItem(DRAFT)||'null');if(d&&d.format===FORMAT)data={...empty(),...d};}catch(e){}for(const u of data.units||[])delete u.image;migrateIds();}

/* ---------- screens ---------- */
const fade=fn=>window.PROTransition?window.PROTransition.run(fn):fn();
function showMenu(){$('listView').hidden=true;$('menuView').hidden=false;for(const k of Object.keys(KINDS))document.querySelector(`[data-count="${k}"]`).textContent=data[k].length+'件';$('menuStats').textContent='パック：'+data.name+'（'+data.packId+'）';$('menuTitle').focus();}
function openKind(k,id=null){kind=k;selectedId=id&&Array.isArray(data[k])&&!find(k,id)&&find(k,pre()+id)?pre()+id:id;$('menuView').hidden=true;$('listView').hidden=false;$('listView').classList.toggle('pack-mode',k==='pack'||k==='test');if(k==='pack'||k==='test'){$('listEyebrow').textContent=k==='pack'?'PACK SETTINGS':'TEST STATE';$('listTitle').textContent=k==='pack'?'パック設定':'試しの状態';renderEditor();$('listTitle').focus();return;}$('listEyebrow').textContent=KINDS[k].en;$('listTitle').textContent=KINDS[k].label;$('listSearch').value='';renderList();renderEditor();$('listTitle').focus();}
function renderList(){if(kind==='pack'||kind==='test')return;const q=$('listSearch').value.trim().toLowerCase(),root=$('itemList');root.replaceChildren();// Search: name / ID, or '#tag' for tags (units, weapons, skills…); several words must all match.
 const words=q.split(/\s+/).filter(Boolean),hit=(x,w)=>w.startsWith('#')?(x.tags||[]).some(t=>String(t).toLowerCase().includes(w.slice(1))):(x.name||'').toLowerCase().includes(w)||shownId(x.id).toLowerCase().includes(w)||(x.tags||[]).some(t=>String(t).toLowerCase().includes(w));
 const list=data[kind].filter(x=>words.every(w=>hit(x,w)));if(!list.length)root.append(el('p',data[kind].length?'見つかりません。':'まだありません。「新しく作る」から始めましょう。','cmd-hint'));
 for(const x of list){const b=el('button',null,'td-item'+(x.id===selectedId?' current':''));b.setAttribute('role','menuitem');b.dataset.item=x.id;const n=issues(kind,x).length;b.append(el('span',x.name||'（名前なし）'),el('small',shownId(x.id)+(n?' ・ ⚠'+n:'')));b.onclick=()=>{selectedId=x.id;renderList();renderEditor();};root.append(b);}}
function display(f,x){const v=get(x,f.key);if(f.type==='id')return shownId(v);if(f.type==='color')return v?'■ '+v:'未設定';if(EXT.display[f.type])return EXT.display[f.type](v,x);if(f.type==='toggle')return v?'ON':'OFF';if(f.type==='refs')return (v||[]).length?(v||[]).map(id=>find(f.ref,id)?.name||'⚠'+id).join('・'):'なし';if(f.type==='tags')return (v||[]).join('・')||'なし';if(f.type==='lineup')return lineupText(v,x.enemyRows);if(f.type==='waves')return (v||[]).length?(v.length+'波'):'なし';if(f.type==='lines')return (v||[]).length?(v.length+'行'):'なし';if(f.type==='effects')return (v||[]).length?v.map(effText).join(' ／ '):'なし';if(f.type==='drops')return (v||[]).length?v.map(d=>(d.unitId?'ユニット '+(find('units',d.unitId)?.name||'⚠'+d.unitId):(find('items',d.itemId)?.name||'⚠'+d.itemId))+' '+C.dropRateText(d)+(d.conds?.list?.length?'（条件付き）':'')).join('・'):'なし';if(f.type==='equipToggle')return x.equip?'ON':'OFF';if(f.type==='pilotToggle')return x.pilotProfile?'ON':'OFF';if(f.type==='flagmap')return flagText(v);if(f.type==='conds')return condsText(v);if(f.type==='skillTree')return (v||[]).length?v.length+'ノード：'+v.map(n=>find('skills',n.skillId)?.name||n.skill?.name||'⚠'+n.skillId).join('→'):'なし';if(f.type==='materials')return (v||[]).length?v.map(m=>(find('units',m.unitId)?.name||'⚠'+m.unitId)+(m.consume===false?'（残す）':'')).join('＋'):'なし';if(f.type==='itemCounts'){const e=Object.entries(v||{});return e.length?e.map(([id,n])=>(find('items',id)?.name||'⚠'+id)+'×'+n).join('・'):'なし';}if(f.type==='choices')return (v||[]).length?v.map(c=>c.text).join('／'):'なし';if(f.type==='events')return (v||[]).length?v.length+'件':'なし';if(f.type==='turnLimit'){const t=(x.rules||[]).find(r=>r.type==='turn_limit');return t?t.value+'TURN':'なし';}if(f.type==='select'){const ch=typeof f.choices==='function'?f.choices(x):f.choices;return v==null?(f.key==='objective.type'?'敵をすべて倒す':'未設定'):(ch[String(v)]??v);}if(v==null||v==='')return '未設定';return String(v);}
const target=()=>kind==='pack'?data:kind==='test'?(data.testState||(data.testState={name:'試しの状態',credits:0,day:1,wins:0})):find(kind,selectedId);
// The maker's test state → the state shape PROCore.evalConds reads. Units: Lv1 base stats of the unit being checked.
function testCtx(extra={}){const t=data.testState||{},one=ids=>Object.fromEntries((ids||[]).map(id=>[id,1]));let now=new Date();if(t.realWeekday!=null){now=new Date(2026,0,4+t.realWeekday);}
 return {credits:t.credits||0,day:t.day||1,wins:t.wins||0,flags:one(t.flagsOn),items:{...(t.items||{})},units:one(t.ownedUnits),cleared:t.cleared||[],stars:{},research:t.research||[],hires:one(t.hired),evolved:t.evolved||[],fused:t.fused||[],now,weekBase:{day:1,weekday:now.getDay()},...extra};}
// Drop conditions consume only when the drop actually happens. The test battle works on a copy (sim) so drops and
// costs carry over between its 10 runs (e.g. "not owned yet" stops after the first drop) without touching testState.
function payCosts(st,costs){for(const c of costs){if(c.credits!=null)st.credits-=c.credits;else st.items[c.itemId]=(st.items[c.itemId]||0)-c.count;}}
function condCheck(cs,extra){const r=C.evalConds(cs,testCtx({rng:()=>0,...extra}));const ct=cs2=>cs2.map(c=>c.credits!=null?c.credits+'Cr':(find('items',c.itemId)?.name||c.itemId)+'×'+c.count).join('・');return (r.ok?'✓ 満たす':'✗ 満たさない')+(r.ok&&r.options.length>1?'（消費はプレイヤーが選ぶ：'+r.options.map(o=>ct(o.costs)).join(' ／ ')+'）':r.costs.length?'（消費：'+ct(r.costs)+'）':'');}
