  row('出現条件',WHEN[w.when||'cleared'],()=>{const ks=Object.keys(WHEN);w.when=ks[(ks.indexOf(w.when||'cleared')+1)%ks.length];if(w.when==='cleared')delete w.value;else w.value=w.value??({turn:3,remaining:1,bossHp:50})[w.when];edit1(i);},'when');
  if(w.when&&w.when!=='cleared')row('値（'+({turn:'TURN',remaining:'体',bossHp:'%'})[w.when]+'）',String(w.value),()=>numberPrompt('値',w.value,({turn:1,remaining:0,bossHp:1})[w.when],({turn:300,remaining:8,bossHp:99})[w.when],v=>{if(v!=null)w.value=v;edit1(i);},()=>edit1(i)),'value');
  row('名前（任意）',w.label||'なし',()=>win('波の名前','例：援軍、指揮官部隊',b=>{const t=el('input');t.id='inputValue';t.value=w.label||'';t.maxLength=40;b.append(t);},[['決定',()=>{const v=$('inputValue').value.trim();if(v)w.label=v;else delete w.label;edit1(i);}],['戻る',()=>edit1(i)]]),'label');
