function linesWindow(f,m){const lines=clone(get(m,f.key)||[]);const draw=()=>win(f.label,'話す人とセリフ。上から順に表示されます。',body=>{lines.forEach((l,i)=>{const box=el('div',null,'td-line');const sp=el('input');sp.placeholder='話す人';sp.value=l.speaker||'';sp.dataset.speaker=i;sp.oninput=()=>{l.speaker=sp.value;};const tx=el('input');tx.placeholder='セリフ';tx.value=l.text||'';tx.dataset.text=i;tx.oninput=()=>{l.text=tx.value;};const x=el('button','この行を消す','secondary');x.type='button';x.onclick=()=>{lines.splice(i,1);draw();};box.append(sp,tx,x);body.append(box);});if(!lines.length)body.append(el('p','まだ会話がありません。','cmd-hint'));},[['＋ 行を追加',()=>{lines.push({speaker:'',text:''});draw();}],['決定',()=>{const clean=lines.filter(l=>l.text.trim()).map(l=>({...(l.speaker.trim()?{speaker:l.speaker.trim()}:{}),text:l.text.trim()}));commit(o=>{set(o,f.key,clean.length?clean:undefined);if(o.story&&!Object.keys(o.story).length)delete o.story;});closeWin();}],['戻る',closeWin]]);draw();}
// Test battle with the published auto-battle engine: player units (up to maxDeploy) vs this mission, 10 runs.
function battleDef(u){const w=x=>{try{return C.weapon(x);}catch(e){return null;}},s=x=>{try{return C.skill({...x});}catch(e){return null;}};const weapons=(u.weaponIds||[]).map(id=>find('weapons',id)).filter(Boolean).map(w).filter(Boolean);return {...clone(u),hp:Number(u.hp)||3000,atk:Number(u.atk)||0,def:Number(u.def)||0,mob:Number(u.mob)||0,acc:Number(u.acc)||0,weapons:weapons.length?weapons:[C.weapon({name:'標準攻撃'})],skills:(u.skillIds||[]).map(id=>find('skills',id)).filter(Boolean).map(s).filter(Boolean),tags:u.tags||[]};}
async function testBattle(m){const B=window.PROBattle,iss=issues('missions',m);if(iss.length){message('テスト戦闘できません',iss);return;}const squad=data.units.filter(u=>u.deploy?.player&&u.crew!=='required').slice(0,m.maxDeploy||4);if(!squad.length){message('テスト戦闘できません',['「味方として使う」がONのユニットがありません。']);return;}
 C.registerTerrains(data.terrains.map(t=>{try{return C.terrain(t);}catch(e){return null;}}).filter(Boolean));const defs=Object.fromEntries(data.units.map(u=>[u.id,battleDef(u)])),rng=B.mulberry32(Date.now()%100000),res={win:0,lose:0,draw:0},turns=[],got={},sim=testCtx({deployed:squad.map(u=>u.id)});for(let i=0;i<10;i++){const ctx=B.buildBattle({allies:squad.map(u=>defs[u.id]),rows:squad.map(u=>u.row||'front'),mission:clone(m),enemyDefs:defs,unitDefs:defs},rng);const r=await B.runBattle(ctx);res[r.outcome]++;turns.push(r.turns);if(r.outcome==='win')for(const d of m.drops||[]){const ok=C.evalConds(d.conds,{...sim,rng});if(!ok.ok)continue;const p=d.odds?d.odds[0]/d.odds[1]:(d.chance??100)/100;if(rng()>=p)continue;payCosts(sim,ok.costs);const lo=d.min??1,hi=d.max??lo,n=lo+Math.floor(rng()*(hi-lo+1)),k=(d.unitId?'u:':'i:')+(d.unitId||d.itemId);got[k]=(got[k]||0)+n;const bag=d.unitId?sim.units:sim.items;bag[d.unitId||d.itemId]=(bag[d.unitId||d.itemId]||0)+n;}}
 const c=C.missionConditions(m,Object.fromEntries(data.units.map(u=>[u.id,u.name])));message('テスト戦闘の結果（10回）',['味方：'+squad.map(u=>u.name).join('・')+'（味方として使うユニットの先頭から最大'+(m.maxDeploy||4)+'体）',c.win,'勝ち '+res.win+' ／ 負け '+res.lose+' ／ 引き分け '+res.draw,'平均 '+(turns.reduce((a,b)=>a+b,0)/turns.length).toFixed(1)+'TURN',...(m.conds?.list?.length?['解放条件（試しの状態）：'+condCheck(m.conds)+(C.evalConds(m.conds,testCtx({rng:()=>0})).costs.length?' ※消費は作戦開始時':'')]:[]),...((m.drops||[]).length?['ドロップ（勝利'+res.win+'回分・試しの状態から続けて判定、入手と消費を反映）：'+(Object.entries(got).map(([k,n])=>(k[0]==='u'?'ユニット '+(find('units',k.slice(2))?.name||k.slice(2)):(find('items',k.slice(2))?.name||k.slice(2)))+'×'+n).join('・')||'なし')]:[])]);}

/* ---------- items: effects, drops, core-format conversion ---------- */
const EFFECT_PARAMS={stat_up_flat:['stat','value'],stat_up_pct:['stat','value'],sortie_buff:['stat','value'],add_tag:['tag'],remove_tag:['tag'],add_weapon:['weaponId'],add_skill:['skillId'],remove_skill:['skillId'],remove_weapon:['name'],recruit_unit:['unitId'],loot_box:['table'],heal_hp_full:[],equip_slot:['value']};
const params=t=>EFFECT_PARAMS[t]||['value'];
const valueRange=t=>t==='equip_slot'?[-3,3]:t==='sortie_buff'?[1,500]:t.endsWith('_pct')?[1,100]:[1,1000000000];
function effText(e){const n=C.effects[e.type]||e.type,p=[];if(e.stat)p.push(C.stats[e.stat]);if(e.value!=null)p.push((e.value>0&&e.type==='equip_slot'?'+':'')+e.value+(e.type.endsWith('_pct')||e.type==='sortie_buff'?'%':''));if(e.tag)p.push('「'+e.tag+'」');if(e.weaponId)p.push(find('weapons',e.weaponId)?.name||'⚠'+e.weaponId);if(e.skillId)p.push(find('skills',e.skillId)?.name||'⚠'+e.skillId);if(e.unitId)p.push(find('units',e.unitId)?.name||'⚠'+e.unitId);if(e.name)p.push(e.name);if(e.table)p.push(e.table.length+'種');return n+(p.length?' '+p.join(' '):'');}
// T&D item → PROCore item (links resolved to embedded copies) for validation.
function itemCore(it){const w=id=>{const x=find('weapons',id);return x?{...x}:{name:'?'};},sk=id=>{const x=find('skills',id);return x?{...x}:{id:'x',name:'?'};};const effects=(it.effects||[]).map(e=>e.type==='add_weapon'?{type:e.type,weapon:w(e.weaponId)}:e.type==='add_skill'?{type:e.type,skill:sk(e.skillId)}:clone(e));const o={...clone(it),id:it.id||'x',effects};if(o.equip)o.equip={stats:{...(it.equip.stats||{})},skillIds:[...(it.equip.skillIds||[])],weaponIds:[...(it.equip.weaponIds||[])]};delete o.note;if(!effects.length)delete o.effects;return o;}
function effectsWindow(it){const list=clone(it.effects||[]);const saveAll=()=>commit(o=>{if(list.length)o.effects=list;else delete o.effects;});
 const defaults=t=>{const e={type:t};for(const p of params(t)){if(p==='value')e.value=t==='equip_slot'?1:t==='sortie_buff'?15:t.endsWith('_pct')?50:100;if(p==='stat')e.stat='atk';if(p==='table')e.table=[];}return e;};
 const top=()=>win('使ったときの効果','8個まで。押すと編集します。',body=>{const l=el('div',null,'cmd-list');list.forEach((e,i)=>{const b=el('button',(i+1)+'. '+effText(e));b.type='button';b.dataset.effect=i;b.onclick=()=>one(i);l.append(b);});if(!list.length)l.append(el('p','効果がありません（装備品・キーアイテムは効果なしでも可）。','cmd-hint'));body.append(l);},[['＋ 効果を追加',()=>{if(list.length>=8)return;pickType(t=>{list.push(defaults(t));one(list.length-1);},top);}],['閉じる',()=>{saveAll();closeWin();}]]);
 const pickType=(done,back)=>win('効果の種類','何が起きるかを選んでください。',body=>{const l=el('div',null,'cmd-list');for(const [k,label] of Object.entries(C.effects)){const b=el('button',label);b.type='button';b.dataset.etype=k;b.onclick=()=>done(k);l.append(b);}body.append(l);},[['戻る',back]]);
 const choose=(title,ch,cur,done,back)=>win(title,'',body=>{const l=el('div',null,'cmd-list');for(const [k,label] of Object.entries(ch)){const b=el('button',(k===cur?'✓ ':'')+label);b.type='button';b.dataset.choice=k;b.onclick=()=>done(k);l.append(b);}if(!Object.keys(ch).length)l.append(el('p','選べるものがありません。先に作ってください。','cmd-hint'));body.append(l);},[['戻る',back]]);
 const tableWin=(table,back)=>win('ランダム箱の中身','重みが大きいほど出やすくなります。',body=>{table.forEach((r,j)=>{const box=el('div',null,'td-line');const sel=el('select');sel.dataset.tableItem=j;for(const x of data.items){const o=el('option',x.name+'（'+shownId(x.id)+'）');o.value=x.id;sel.append(o);}sel.value=r.itemId;sel.onchange=()=>{r.itemId=sel.value;};const nums=el('div',null,'td-nums');for(const [k,l2] of [['weight','重み'],['min','最小'],['max','最大']]){const lab=el('label',l2),inp=el('input');inp.type='number';inp.value=r[k];inp.oninput=()=>{r[k]=Number(inp.value);};lab.append(inp);nums.append(lab);}const x=el('button','この行を消す','secondary');x.type='button';x.onclick=()=>{table.splice(j,1);tableWin(table,back);};box.append(sel,nums,x);body.append(box);});if(!table.length)body.append(el('p','中身がありません。','cmd-hint'));},[['＋ 行を追加',()=>{if(!data.items.length)return;table.push({itemId:data.items[0].id,weight:1,min:1,max:1});tableWin(table,back);}],['戻る',back]]);
 const one=i=>{const e=list[i];win('効果 '+(i+1),'',body=>{const l=el('div',null,'cmd-list');const row=(label,val,fn,key)=>{const b=el('button',null,'unit-row setting-row td-row');b.type='button';b.dataset.efield=key;b.append(el('span',label),el('b',val));b.onclick=fn;l.append(b);};
  row('種類',C.effects[e.type],()=>pickType(t=>{list[i]=defaults(t);one(i);},()=>one(i)),'type');
  for(const p of params(e.type)){if(p==='value'){const [mn,mx]=valueRange(e.type);row('効果の大きさ',String(e.value),()=>numberPrompt('効果の大きさ',e.value,mn,mx,v=>{if(v!=null)e.value=v;one(i);},()=>one(i)),'value');}
   if(p==='stat')row('対象の能力',C.stats[e.stat],()=>choose('対象の能力',Object.fromEntries(Object.entries(C.stats).filter(([k])=>!(e.type==='sortie_buff'&&k==='hp'))),e.stat,k=>{e.stat=k;one(i);},()=>one(i)),'stat');
   if(p==='tag'||p==='name')row(p==='tag'?'タグ':'外す武装の名前（空欄=最後に足した武装）',e[p]||'未設定',()=>win(p==='tag'?'タグ':'武装の名前','',b=>{const t=el('input');t.id='inputValue';t.value=e[p]||'';b.append(t);},[['決定',()=>{const v=$('inputValue').value.trim();if(v)e[p]=v;else delete e[p];one(i);}],['戻る',()=>one(i)]]),p);
   if(p==='weaponId'||p==='skillId'||p==='unitId'){const rk={weaponId:'weapons',skillId:'skills',unitId:'units'}[p];row(KINDS[rk].label,e[p]?(find(rk,e[p])?.name||'⚠'+e[p]):'未選択',()=>choose(KINDS[rk].label+'を選ぶ',Object.fromEntries(data[rk].map(x=>[x.id,x.name+'（'+x.id+'）'])),e[p],k=>{e[p]=k;one(i);},()=>one(i)),p);}
   if(p==='table')row('中身',e.table.length+'種',()=>tableWin(e.table,()=>one(i)),'table');}
  body.append(l);},[['この効果を削除',()=>{list.splice(i,1);top();}],['一覧へ戻る',top]]);};
 top();}
// Drops: each row is an item or a unit, with a rate, counts and an optional condition set.
function dropsWindow(m){const drops=clone(m.drops||[]);const draw=()=>win('ドロップ','勝利したときに手に入るアイテム・ユニット。確率は % か 1/8 のような分数。行ごとに条件（例：まだ持っていない）を付けられます。',body=>{drops.forEach((d,j)=>{const box=el('div',null,'td-line');const kindB=el('button',d.unitId?'種類：ユニット':'種類：アイテム','secondary');kindB.type='button';kindB.dataset.dropKind=j;kindB.onclick=()=>{if(d.unitId){delete d.unitId;d.itemId=data.items[0]?.id;}else{delete d.itemId;d.unitId=data.units[0]?.id;}draw();};const sel=el('select');sel.dataset.dropItem=j;const list=d.unitId?data.units:data.items;for(const x of list){const o=el('option',x.name+'（'+shownId(x.id)+'）');o.value=x.id;sel.append(o);}sel.value=d.unitId||d.itemId;sel.onchange=()=>{if(d.unitId)d.unitId=sel.value;else d.itemId=sel.value;};const nums=el('div',null,'td-nums');const rate=el('label','確率'),ri=el('input');ri.value=d.odds?d.odds[0]+'/'+d.odds[1]:(d.chance??100);ri.dataset.dropRate=j;ri.oninput=()=>{try{const p=C.parseDropRate(ri.value);delete d.chance;delete d.odds;Object.assign(d,p);}catch(e){}};rate.append(ri);nums.append(rate);for(const [k,l2] of [['min','最小個数'],['max','最大個数']]){const lab=el('label',l2),inp=el('input');inp.type='number';inp.value=d[k];inp.oninput=()=>{d[k]=Number(inp.value);};lab.append(inp);nums.append(lab);}const cb=el('button','条件：'+condsText(d.conds),'secondary');cb.type='button';cb.dataset.dropConds=j;cb.onclick=()=>condsEditor('ドロップの条件',d.conds,cs=>{if(cs)d.conds=cs;else delete d.conds;draw();},draw);const x=el('button','この行を消す','secondary');x.type='button';x.onclick=()=>{drops.splice(j,1);draw();};box.append(kindB,sel,nums,cb,x);body.append(box);});if(!drops.length)body.append(el('p','ドロップはありません。','cmd-hint'));},
 [['＋ 行を追加',()=>{if(data.items.length)drops.push({itemId:data.items[0].id,chance:50,min:1,max:1});else if(data.units.length)drops.push({unitId:data.units[0].id,chance:50,min:1,max:1});draw();}],['決定',()=>{for(const d of drops){const e=dropIssue(d);if(e){$('inputError').textContent=e;return;}}commit(o=>{if(drops.length)o.drops=drops;else delete o.drops;});closeWin();}],['戻る',closeWin]]);draw();}
// Unit drops are T&D-only; rate and counts are checked with the same rules as item drops.
function dropIssue(d){try{C.drop({...d,itemId:d.itemId||d.unitId||'x'});}catch(e){return e.message;}if(!d.itemId&&!d.unitId)return 'ドロップの対象が未選択です';return '';}

/* ---------- flags, unlock conditions, choices and events ---------- */
// Where a flag is set (with its value) and where it is required, for the flag screen.
function flagSites(id){const set=[],use=[];for(const m of data.missions){const v=m.requires?.flags?.[id];if(v!==undefined)use.push([m,'解放条件：'+(v?'ON':'OFF')+'が必要']);for(const [r,l] of [['win','勝利'],['lose','敗北'],['draw','引き分け']]){const x=m.resultFlags?.[r]?.[id];if(x!==undefined)set.push([m,l+'で'+(x?'ON':'OFF')]);}(m.events||[]).forEach((e,i)=>{const x=e.flags?.[id];if(x!==undefined)set.push([m,'イベント'+(i+1)+'で'+(x?'ON':'OFF')]);});(m.story?.choices||[]).forEach((c,i)=>{const x=c.flags?.[id];if(x!==undefined)set.push([m,'選択肢「'+c.text+'」で'+(x?'ON':'OFF')]);});}return {set,use};}
function newFlag(name){const f={id:nextId('flags'),name:name||'新しいフラグ',desc:''};data.flags.push(f);return f;}
const flagText=map=>{const e=Object.entries(map||{});return e.length?e.map(([id,v])=>(find('flags',id)?.name||'⚠'+id)+'='+(v?'ON':'OFF')).join('・'):'なし';};
// Each flag cycles 変更しない → ON → OFF; new flags can be created on the spot.
function flagMapWindow(title,map0,done,back){const map={...(map0||{})};const draw=()=>win(title,'押すたびに「指定しない → ON → OFF」と切り替わります。',body=>{const l=el('div',null,'cmd-list');for(const f of data.flags){const v=map[f.id],b=el('button',null,'unit-row setting-row td-row');b.type='button';b.dataset.flag=f.id;b.append(el('span',f.name+'（'+f.id+'）'),el('b',v===undefined?'指定しない':v?'ON':'OFF'));b.onclick=()=>{if(v===undefined)map[f.id]=true;else if(v)map[f.id]=false;else delete map[f.id];draw();};l.append(b);}if(!data.flags.length)l.append(el('p','フラグがまだありません。','cmd-hint'));body.append(l);},[['＋ 新しいフラグを作る',()=>win('新しいフラグ','フラグの名前（例：森ルートを選んだ）',b=>{const t=el('input');t.id='inputValue';b.append(t);},[['作る',()=>{const n=$('inputValue').value.trim();if(!n){$('inputError').textContent='名前を入れてください';return;}const f=newFlag(n);map[f.id]=true;save();draw();}],['戻る',draw]])],['決定',()=>done(Object.keys(map).length?map:undefined)],['戻る',back]]);draw();}
function choicesWindow(m){const list=clone(m.story?.choices||[]);const saveAll=()=>commit(o=>{o.story=o.story||{};if(list.length)o.story.choices=list;else delete o.story.choices;if(!Object.keys(o.story).length)delete o.story;});
 const top=()=>win('作戦前の選択肢','8個まで。作戦前の会話のあとに表示されます。',body=>{const l=el('div',null,'cmd-list');list.forEach((c,i)=>{const b=el('button',(i+1)+'. '+(c.text||'（本文なし）')+' ／ '+flagText(c.flags));b.type='button';b.dataset.choiceItem=i;b.onclick=()=>one(i);l.append(b);});if(!list.length)l.append(el('p','選択肢はありません。','cmd-hint'));body.append(l);},[['＋ 選択肢を追加',()=>{if(list.length>=8)return;list.push({text:'新しい選択肢',flags:{},lines:[]});one(list.length-1);}],['閉じる',()=>{saveAll();closeWin();}]]);
 const one=i=>{const c=list[i];win('選択肢 '+(i+1),'',body=>{const l=el('div',null,'cmd-list');const row=(label,val,fn,key)=>{const b=el('button',null,'unit-row setting-row td-row');b.type='button';b.dataset.cfield=key;b.append(el('span',label),el('b',val));b.onclick=fn;l.append(b);};
  row('選択肢の文',c.text||'未設定',()=>win('選択肢の文','',b=>{const t=el('input');t.id='inputValue';t.value=c.text||'';t.maxLength=100;b.append(t);},[['決定',()=>{const v=$('inputValue').value.trim();if(!v){$('inputError').textContent='本文は必須です';return;}c.text=v;one(i);}],['戻る',()=>one(i)]]),'text');
  row('表示条件',condsText(c.conds),()=>condsEditor('この選択肢を表示する条件',c.conds,v=>{if(v)c.conds=v;else delete c.conds;one(i);},()=>one(i)),'conds');
  row('立てるフラグ',flagText(c.flags),()=>flagMapWindow('選んだら立てるフラグ',c.flags,v=>{c.flags=v||{};one(i);},()=>one(i)),'flags');
  row('選んだあとの会話',(c.lines||[]).length+'行',()=>linesEditor('選んだあとの会話',c.lines||[],v=>{c.lines=v;one(i);},()=>one(i)),'lines');body.append(l);},[['この選択肢を削除',()=>{list.splice(i,1);top();}],['一覧へ戻る',top]]);};top();}
