function parseFile(text){const t=text.trim();try{return JSON.parse(t);}catch(e){}const m=t.match(/=\s*(\{[\s\S]*\})\s*;?\s*$/);if(m)return JSON.parse(m[1]);throw Error('JSON／統合JSとして読めませんでした');}
function applyImport(src,title){let res;try{res=convert(src);}catch(e){message('読み込めませんでした',[e.message]);return;}const r=res.report,d=res.data;message(title,['ユニット'+d.units.length+'体・武装'+d.weapons.length+'件・スキル'+d.skills.length+'件・作戦'+d.missions.length+'件・アイテム'+d.items.length+'件・フラグ'+d.flags.length+'個・独自の地形'+d.terrains.length+'個・研究'+d.research.length+'件・雇用'+d.hires.length+'件・進化'+d.evolutions.length+'件・合成'+d.fusions.length+'件。今のデータと置き換えます。','変換：'+(r.converted.length?'':'なし'),...r.converted.map(x=>'・'+x),'切り捨て：'+(r.dropped.length?'':'なし'),...r.dropped.map(x=>'・'+x)],[['置き換える',()=>{data=d;migrateIds();selectedId=null;save();$('msgWin').close();fade(showMenu);}],['やめる',()=>$('msgWin').close()]]);}
function loadBase(){const need=[['VAIS_UNIT_PACK','../outer_ops_units.js'],['VAIS_MISSION_PACK','../outer_ops_missions.js'],['VAIS_ITEM_PACK','../outer_ops_items.js']].filter(([g])=>!window[g]);const go=()=>applyImport({...window.VAIS_UNIT_PACK,missions:window.VAIS_MISSION_PACK?.missions||[],items:window.VAIS_ITEM_PACK?.items||[],research:window.VAIS_ITEM_PACK?.research||[]},'PRO・Dの基本データ');if(!need.length)return go();let left=need.length;for(const [,src] of need){const s=document.createElement('script');s.src=src;s.onload=()=>{if(!--left)go();};s.onerror=()=>message('読み込めませんでした',['基本データのファイルが見つかりません。']);document.head.append(s);}}
// Pack output: the draft as a pack the Tactical hub can load (records and checks first; items with problems are reported,
// and the hub skips content it cannot use).
function outputPack(){const probs=[];for(const k of Object.keys(KINDS))for(const x of Array.isArray(data[k])?data[k]:[])for(const p of issues(k,x))probs.push((KINDS[k].label)+'「'+(x.name||x.id)+'」：'+p);
 const run=()=>{const text=JSON.stringify({...data,testState:undefined,format:FORMAT,version:1,pack:true,exportedAt:new Date().toISOString()},null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=(data.packId||'td-pack')+'.pack.json';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);message('パック出力',['「'+a.download+'」を保存しました。タクティカルの拠点 → 記録・設定 → データの読み込み元 → パックファイルを読み込む で遊べます。']);};
 if(!probs.length){run();return;}message('問題があります（'+probs.length+'件）',[...probs.slice(0,12),...(probs.length>12?['ほか'+(probs.length-12)+'件']:[]),'このまま出力すると、遊ぶ側では使えないデータ（作戦など）が読み込まれません。'],[['このまま出力する',()=>{$('msgWin').close();run();}],['戻る',()=>$('msgWin').close()]]);}
function exportPack(){const text=JSON.stringify({...data,testState:undefined,format:FORMAT,version:1,exportedAt:new Date().toISOString()},null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=(data.packId||'td-pack')+'.td.json';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);message('書き出し',['T&D形式（'+a.download+'）で保存しました。ゲームの「データの読み込み元」で読み込めます。']);}

